package controller.model.repository;
import java.time.LocalDateTime; import jakarta.persistence.Entity; import jakarta.persistence.GeneratedValue; import jakarta.persistence.GenerationType; import jakarta.persistence.Id; import jakarta.persistence.Table;
@Entity @Table(name="blood_requests")
public class BloodRequest {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String patientName; private String hospital; private String bloodType; private Integer units; private String priority; private String status; private LocalDateTime createdAt; private java.time.LocalDate neededDate; private String reason; private String requester; private Long requesterId; private LocalDateTime dispatchedAt; private Integer dispatchedUnits; private String dispatchNotes; private java.time.LocalDate scheduledDispatchDate; private java.time.LocalDate deliveryDate; private String evaluation;
 public Long getId(){return id;} public void setId(Long v){id=v;} public String getPatientName(){return patientName;} public void setPatientName(String v){patientName=v;} public String getHospital(){return hospital;} public void setHospital(String v){hospital=v;} public String getBloodType(){return bloodType;} public void setBloodType(String v){bloodType=v;} public Integer getUnits(){return units;} public void setUnits(Integer v){units=v;} public String getPriority(){return priority;} public void setPriority(String v){priority=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;}
 public java.time.LocalDate getNeededDate(){return neededDate;} public void setNeededDate(java.time.LocalDate v){neededDate=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public String getRequester(){return requester;} public void setRequester(String v){requester=v;} public LocalDateTime getDispatchedAt(){return dispatchedAt;} public void setDispatchedAt(LocalDateTime v){dispatchedAt=v;} public Integer getDispatchedUnits(){return dispatchedUnits;} public void setDispatchedUnits(Integer v){dispatchedUnits=v;} public String getDispatchNotes(){return dispatchNotes;} public void setDispatchNotes(String v){dispatchNotes=v;} public java.time.LocalDate getScheduledDispatchDate(){return scheduledDispatchDate;} public void setScheduledDispatchDate(java.time.LocalDate v){scheduledDispatchDate=v;} public java.time.LocalDate getDeliveryDate(){return deliveryDate;} public void setDeliveryDate(java.time.LocalDate v){deliveryDate=v;}
 public String getEvaluation(){return evaluation;} public void setEvaluation(String v){evaluation=v;}
 public Long getRequesterId(){return requesterId;} public void setRequesterId(Long v){requesterId=v;}
}
